pub fn tech(id: i32) -> Option<&'static Tech> {
    // erster Eintrag je ID, wie find(); Tabelle einmal aufgebaut
    static NR: std::sync::OnceLock<Vec<i16>> = std::sync::OnceLock::new();
    let m = NR.get_or_init(|| {
        let max = TECH.iter().map(|t| t.id).max().unwrap_or(0).max(0) as usize;
        let mut m = vec![-1i16; max + 1];
        for (i, t) in TECH.iter().enumerate() { if t.id >= 0 && m[t.id as usize] < 0 { m[t.id as usize] = i as i16; } }
        m
    });
    if id < 0 { return None; }
    m.get(id as usize).and_then(|&i| if i >= 0 { Some(&TECH[i as usize]) } else { None })
}
pub fn einheit(typ: i32) -> Option<&'static Einheit> { EINHEIT.iter().find(|e| e.typ == typ) }
